<?php require_once '../config/auth.php';require_admin();$page_title='Users';$base='../';$rows=$pdo->query('SELECT id,name,email,role,status,last_login,created_at FROM users ORDER BY created_at DESC')->fetchAll();include '../partials/header.php';?><div class="mb-3"><h4>Team Users</h4><p class="text-muted">Manage CRM access.</p></div><div class="cardx table-responsive"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Last login</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><span class="status"><?=e($r['role'])?></span></td><td><?=e($r['status'])?></td><td><?=e($r['last_login']??'Never')?></td></tr><?php endforeach;?></tbody></table></div><?php include '../partials/footer.php';?>